answer.content:
// 1. Variable Declarations
$primary-color: #4f46e5;
$text-color: #1f2937;
$border-radius-base: 8px;
$font-stack: 'Inter', -apple-system, sans-serif;

// 2. Applying Variables
.profile-card {
  background-color: #ffffff;
  border-radius: $border-radius-base;
  font-family: $font-stack;
  color: $text-color;
  border: 1px solid #e5e7eb;

  .card-title {
    color: $primary-color;
  }
}

$theme-mode: 'light'; // Global variable

.dark-theme-panel {
  // Local variable: shadows the global variable ONLY within this block
  $local-accent: #38bdf8;

  // Using !global modifies the outer global variable value
  $theme-mode: 'dark' !global;

  color: $local-accent;
}

.status-display {
  // Reflects the newly altered global variable value ('dark')
  content: "Current mode: #{$theme-mode}";
}

.nav {
  background-color: #1e293b;
  padding: 1rem 2rem;

  ul {
    display: flex;
    list-style: none;
    margin: 0;
    padding: 0;
    gap: 1.5rem;

    li {
      a {
        color: #e2e8f0;
        text-decoration: none;
        font-weight: 500;
        transition: color 0.2s ease;

        &:hover {
          color: #38bdf8;
        }
      }
    }
  }
}

.btn {
  display: inline-block;
  padding: 0.6rem 1.2rem;
  font-size: 0.9rem;
  border-radius: 4px;
  cursor: pointer;
  border: none;

  // Pseudo-classes
  &:hover {
    opacity: 0.9;
  }

  &:active {
    transform: translateY(1px);
  }

  // BEM modifier (.btn--primary)
  &--primary {
    background-color: #2563eb;
    color: #ffffff;
  }

  // Contextual parent selector (.dark-mode .btn)
  .dark-mode & {
    border: 1px solid rgba(255, 255, 255, 0.2);
  }
}

.editorial-banner {
  // Nesting sub-properties of 'font'
  font: {
    family: 'Georgia', serif;
    size: 1.25rem;
    weight: 600;
    style: italic;
  }

  // Nesting sub-properties of 'border'
  border: {
    style: solid;
    width: 2px;
    color: #cbd5e1;
  }
}

@mixin generate-theme-variant($name, $color-value) {
  // 1. Interpolation in selector class names
  .theme-#{$name} {
    // 2. Interpolation in CSS custom properties
    --current-theme-color: #{$color-value};

    background-color: var(--current-theme-color);
    border-left: 4px solid darken($color-value, 15%);
  }
}

// Invocations
@include generate-theme-variant('success', #10b981);
@include generate-theme-variant('danger', #ef4444);
